def best_day(path):
    lines = open(path).read().splitlines()[1:]
    days, closes = [], []
    for line in lines:
        d, c = line.split(",")
        days.append(int(d))
        closes.append(int(c))
    best = 1
    for i in range(2, len(closes)):
        if closes[i] - closes[i - 1] > closes[best] - closes[best - 1]:
            best = i
    return days[best]
